cat > /app/output/styles.css <<'EOF'
:root {
  --bg: oklch(0.99 0.003 258);
  --surface: oklch(1 0 0);
  --surface-alt: oklch(0.97 0.01 258);
  --text: oklch(0.24 0.03 262);
  --muted: oklch(0.55 0.03 262);
  --primary: oklch(0.55 0.23 264);
  --primary-strong: oklch(0.48 0.23 264);
  --accent: oklch(0.72 0.2 28);
  --accent-2: oklch(0.78 0.21 145);
  --border: oklch(0.9 0.01 258);
  --shadow: 0 8px 30px color-mix(in oklab, var(--primary) 12%, transparent);
  --radius: 16px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; font-family: 'Inter', system-ui, sans-serif; background: var(--bg); color: var(--text); }
a { color: inherit; text-decoration: none; }
.container { width: min(1120px, 92%); margin: 0 auto; }
header { position: sticky; top: 0; z-index: 20; background: color-mix(in oklab, white 88%, var(--primary) 12%); border-bottom: 1px solid var(--border); backdrop-filter: blur(8px); }
.nav { display: flex; align-items: center; justify-content: space-between; padding: 14px 0; gap: 16px; }
.brand { font-weight: 800; font-size: 1.2rem; letter-spacing: -0.02em; }
.nav-links { display: flex; gap: 14px; flex-wrap: wrap; align-items: center; }
.nav-links a { padding: 8px 10px; border-radius: 10px; color: var(--muted); font-weight: 600; }
.nav-links a.active, .nav-links a:hover { background: var(--surface); color: var(--text); }
.btn { display: inline-flex; align-items: center; justify-content: center; padding: 12px 18px; border-radius: 12px; font-weight: 700; border: 1px solid transparent; transition: .2s ease; cursor: pointer; }
.btn-primary { background: linear-gradient(135deg, var(--primary), var(--primary-strong)); color: white; box-shadow: var(--shadow); }
.btn-primary:hover { transform: translateY(-2px); }
.btn-ghost { background: var(--surface); border-color: var(--border); }
.hero { padding: 72px 0 24px; }
.hero-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 28px; align-items: center; }
.hero h1 { font-size: clamp(2rem, 4vw, 3.5rem); line-height: 1.05; letter-spacing: -0.03em; margin: 0 0 16px; }
.hero p { color: var(--muted); font-size: 1.1rem; margin: 0 0 24px; max-width: 62ch; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.preview-card { background: var(--surface); border: 1px solid var(--border); border-radius: 20px; padding: 16px; box-shadow: var(--shadow); }
.tab-switch { display: inline-flex; background: var(--surface-alt); border-radius: 12px; padding: 4px; margin-bottom: 14px; }
.tab-switch button { border: 0; background: transparent; padding: 9px 12px; border-radius: 10px; font-weight: 700; color: var(--muted); cursor: pointer; }
.tab-switch button.active { background: var(--surface); color: var(--text); box-shadow: 0 2px 8px rgba(0,0,0,.08); }
.stats { margin: 26px 0 42px; background: linear-gradient(90deg, var(--primary), color-mix(in oklab, var(--primary) 72%, var(--accent))); border-radius: 18px; color: #fff; }
.stats-grid { display: grid; grid-template-columns: repeat(3,1fr); }
.stat { padding: 24px; text-align: center; }
.stat strong { display: block; font-size: clamp(1.4rem,2.5vw,2rem); }
.section { padding: 62px 0; }
.section h2 { font-size: clamp(1.6rem, 2.5vw, 2.4rem); margin: 0 0 18px; letter-spacing: -0.02em; }
.section-intro { color: var(--muted); margin-bottom: 24px; max-width: 70ch; }
.grid-3, .grid-4, .grid-2 { display: grid; gap: 16px; }
.grid-2 { grid-template-columns: repeat(2,1fr); }
.grid-3 { grid-template-columns: repeat(3,1fr); }
.grid-4 { grid-template-columns: repeat(4,1fr); }
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; box-shadow: 0 4px 20px rgba(18,24,40,.06); transition: .2s ease; }
.card:hover { transform: translateY(-3px); box-shadow: var(--shadow); }
.card h3 { margin: 0 0 10px; }
.card p, .card li { color: var(--muted); }
.integrations { display: grid; grid-template-columns: repeat(6,1fr); gap: 12px; }
.logo { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; text-align: center; padding: 14px 8px; font-weight: 700; color: var(--muted); }
.tabs { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
.tabs button { border:1px solid var(--border); background: var(--surface); border-radius: 999px; padding: 8px 12px; font-weight: 700; cursor: pointer; }
.tabs button.active { background: var(--primary); color: #fff; border-color: var(--primary); }
.tab-panel { display: none; }
.tab-panel.active { display: grid; }
.pricing { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }
.price { font-size: 2rem; font-weight: 800; }
.testimonial-wrap { position: relative; }
.testimonial { display: none; }
.testimonial.active { display: block; }
.carousel-controls { display: flex; gap: 8px; margin-top: 12px; }
.icon-btn { border: 1px solid var(--border); background: var(--surface); border-radius: 10px; padding: 8px 12px; cursor: pointer; }
.faq-item { background: var(--surface); border:1px solid var(--border); border-radius: 12px; margin-bottom: 10px; overflow: hidden; }
.faq-question { width:100%; border:0; background:transparent; text-align:left; padding:14px 16px; font-weight:700; cursor:pointer; }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height .25s ease; padding: 0 16px; color: var(--muted); }
.faq-item.open .faq-answer { max-height: 180px; padding-bottom: 14px; }
.cta-band { background: linear-gradient(125deg, var(--primary), var(--accent-2)); color: #fff; border-radius: 20px; padding: 30px; text-align: center; }
footer { padding: 40px 0; color: var(--muted); }
.reveal { opacity: 0; transform: translateY(16px); transition: .5s ease; }
.reveal.visible { opacity: 1; transform: translateY(0); }
@media (max-width: 980px){
  .hero-grid,.grid-4,.grid-3,.pricing,.integrations { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 700px){
  .hero-grid,.grid-2,.grid-3,.grid-4,.pricing,.stats-grid,.integrations { grid-template-columns: 1fr; }
  .nav{align-items:flex-start; flex-direction:column;}
}
EOF

cat > /app/output/script.js <<'EOF'
document.querySelectorAll('.tab-switch').forEach((wrap)=>{
  const buttons=[...wrap.querySelectorAll('button')];
  const target=wrap.dataset.target;
  const panes=[...document.querySelectorAll(`[data-group="${target}"]`)];
  buttons.forEach(btn=>btn.addEventListener('click',()=>{
    buttons.forEach(b=>b.classList.remove('active')); btn.classList.add('active');
    panes.forEach(p=>p.hidden=p.dataset.view!==btn.dataset.view);
  }));
});

document.querySelectorAll('.tabs').forEach((tabs)=>{
  const btns=[...tabs.querySelectorAll('button')];
  const key=tabs.dataset.tabs;
  const panels=[...document.querySelectorAll(`.tab-panel[data-tabs="${key}"]`)];
  btns.forEach(btn=>btn.addEventListener('click',()=>{
    btns.forEach(b=>b.classList.remove('active')); btn.classList.add('active');
    panels.forEach(p=>p.classList.toggle('active', p.dataset.panel===btn.dataset.panel));
  }));
});

document.querySelectorAll('[data-carousel]').forEach((c)=>{
  const slides=[...c.querySelectorAll('.testimonial')];
  let idx=0;
  const show=(i)=>slides.forEach((s,n)=>s.classList.toggle('active',n===i));
  c.querySelector('[data-prev]')?.addEventListener('click',()=>{idx=(idx-1+slides.length)%slides.length;show(idx);});
  c.querySelector('[data-next]')?.addEventListener('click',()=>{idx=(idx+1)%slides.length;show(idx);});
});

document.querySelectorAll('.faq-question').forEach((q)=>{
  q.addEventListener('click',()=> q.closest('.faq-item').classList.toggle('open'));
});

const observer=new IntersectionObserver((entries)=>{
  entries.forEach(e=>{ if(e.isIntersecting) e.target.classList.add('visible'); });
},{threshold:0.15});
document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
EOF

